mapper.select:
SELECT COUNT(*) FROM ${table}
WHERE cmd_type = #{cmdType} AND biz_key = #{bizKey}
  AND status IN ('PENDING', 'RUNNING')

mapper.update:
UPDATE ${table} SET status = 'RUNNING', claim_token = #{token}, gmt_modified = NOW()
WHERE status = 'PENDING' AND next_run_at <= #{now}
  AND id IN (SELECT id FROM (SELECT id FROM ${table}
             WHERE status = 'PENDING' AND next_run_at <= #{now}
             ORDER BY id LIMIT #{limit}) t)

UPDATE ${table} SET status = 'PENDING', claim_token = NULL, gmt_modified = NOW()
WHERE status = 'RUNNING' AND gmt_modified < #{threshold}
LIMIT #{limit}

mapper.select:
SELECT COUNT(*) FROM ${table} WHERE 1 = 1
AND status = #{statusCode}
AND cmd_type = #{cmdType}

SELECT * FROM ${table} WHERE 1 = 1
AND status = #{statusCode}
AND cmd_type = #{cmdType}
ORDER BY id DESC LIMIT #{size} OFFSET #{offset}
